package me.kright.gametools.pga3d

import scala.annotation.targetName
import me.kright.gametools.flatarray.FlatDoubleSerializer
import me.kright.gametools.mathutil.CanEqualWithEps


/**
 * A translator: translation of 3d space, applied with translator.sandwich(obj). Moves points but not vectors.
 * A translator is the exponent of a Pga3dBivectorWeight (bivectorWeight.exp), and translator.log returns that bivector back.
 *
 * Variable fields: wx, wy, wz.
 * Constant fields: s = 1.0.
 * Basis blade coefficients: wx = wx, wy = wy, wz = wz, s = 1.0.
 *
 * Generated by pgaNdCodeGen (me.kright.gametools.pga.codegen.scalagen.pga3d.runScalaCodeGen).
 * Do not edit by hand: change the generator and re-run it.
 */
final case class Pga3dTranslator(wx: Double = 0.0,
                                 wy: Double = 0.0,
                                 wz: Double = 0.0) derives CanEqual, CanEqualWithEps, FlatDoubleSerializer:
  inline val s = 1.0

  override def toString: String =
    s"Pga3dTranslator(wx = $wx, wy = $wy, wz = $wz)"

  def dual: Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = wz,
      xz = -wy,
      yz = wx,
      i = 1.0,
    )

  def weight: Pga3dBivectorWeight =
    Pga3dBivectorWeight(
      wx = wx,
      wy = wy,
      wz = wz,
    )

  def bulk: Double =
    1.0

  @targetName("unaryMinus")
  def unary_- : Pga3dProjectiveTranslator =
    Pga3dProjectiveTranslator(
      s = -1.0,
      wx = -wx,
      wy = -wy,
      wz = -wz,
    )

  def reverse: Pga3dTranslator =
    Pga3dTranslator(
      wx = -wx,
      wy = -wy,
      wz = -wz,
    )

  def antiReverse: Pga3dTranslator =
    Pga3dTranslator(
      wx = -wx,
      wy = -wy,
      wz = -wz,
    )

  def bulkNormSquare: Double = 1.0

  def bulkNorm: Double = 1.0

  def normalizedByBulk: Pga3dTranslator = this

  def weightNormSquare: Double =
    (wx * wx + wy * wy + wz * wz)

  def weightNorm: Double =
    Math.sqrt(weightNormSquare)

  def normalizedByWeight =
    this / weightNorm

  def normSquare: Double =
    (1.0 + wx * wx + wy * wy + wz * wz)

  def norm: Double =
    Math.sqrt(normSquare)

  def normalizedByNorm =
    this / norm

  @targetName("times")
  def *(r: Double): Pga3dProjectiveTranslator =
    Pga3dProjectiveTranslator(
      s = r,
      wx = r * wx,
      wy = r * wy,
      wz = r * wz,
    )

  /** multiplies by the reciprocal: one division instead of one per component, at the cost of one extra rounding (~0.5 ulp) */
  @targetName("div")
  def /(r: Double): Pga3dProjectiveTranslator =
    this * (1.0 / r)

  @targetName("plus")
  def +(r: Pga3dTranslator): Pga3dProjectiveTranslator =
    Pga3dProjectiveTranslator(
      s = 2.0,
      wx = (r.wx + wx),
      wy = (r.wy + wy),
      wz = (r.wz + wz),
    )

  @targetName("minus")
  def -(r: Pga3dTranslator): Pga3dBivectorWeight =
    Pga3dBivectorWeight(
      wx = (wx - r.wx),
      wy = (wy - r.wy),
      wz = (wz - r.wz),
    )

  def madd(r: Pga3dTranslator, mult: Double): Pga3dProjectiveTranslator =
    Pga3dProjectiveTranslator(
      s = (1.0 + mult),
      wx = (wx + mult * r.wx),
      wy = (wy + mult * r.wy),
      wz = (wz + mult * r.wz),
    )

  /** componentwise product on the raw fields; NOT a geometric-algebra operation (basis-dependent) */
  def scale(r: Pga3dTranslator): Pga3dTranslator =
    Pga3dTranslator(
      wx = wx * r.wx,
      wy = wy * r.wy,
      wz = wz * r.wz,
    )

  /** componentwise 1/x on the raw fields (a zero field yields Infinity); NOT the multiplicative inverse */
  def reciprocal: Pga3dTranslator =
    Pga3dTranslator(
      wx = 1.0 / wx,
      wy = 1.0 / wy,
      wz = 1.0 / wz,
    )

  def log: Pga3dBivectorWeight =
    Pga3dBivectorWeight(
      wx = wx,
      wy = wy,
      wz = wz,
    )

  /** the fractional power of the motion: pow(0.5) is the half motion, pow(2.0) applies it twice */
  def pow(t: Double): Pga3dTranslator =
